package settings

import (
	"context"
	"reflect"
	"strings"
	"testing"
)

func boolPtr(b bool) *bool { return &b }

// TestSynthesizeFromLegacy covers the legacy → v2 mapping. Each case sets
// minimal legacy state, runs the synthesizer, and asserts the v2 fields
// that the case is meant to exercise. Fields not asserted are intentionally
// allowed to take their default values.
func TestSynthesizeFromLegacy(t *testing.T) {
	tests := []struct {
		name   string
