			},
		},
		{
			name: "checkpoints_version=2 → primary v2",
			legacy: &EntireSettings{
				Enabled:         true,
				StrategyOptions: map[string]any{"checkpoints_version": float64(2)},
			},
			check: func(t *testing.T, got *Settings) {
